"""OpenAI Responses API client using only Python's standard library."""

import json
import os
import urllib.request


DEFAULT_URL = "https://api.openai.com/v1/responses"


def send_prompt(prompt, api_key=None, model="gpt-4o", url=DEFAULT_URL):
    """Send a private text prompt to OpenAI's Responses API."""
    api_key = api_key or os.environ.get("OPENAI_API_KEY")
    if not api_key:
        raise ValueError("API key required. Set OPENAI_API_KEY or pass api_key.")

    payload = {
        "model": model,
        "input": prompt,
    }

    data = json.dumps(payload).encode("utf-8")

    req = urllib.request.Request(
        url,
        data=data,
        headers={
            "Content-Type": "application/json",
            "Authorization": f"Bearer {api_key}",
        },
        method="POST",
    )

    with urllib.request.urlopen(req) as resp:
        return json.loads(resp.read().decode("utf-8"))
